'use client';


const image1 = <img
  className=" "
  id="image0_5_5"
  width="114"
  height="130"

  alt='thiis default image'
  src="data:image/png;base64,"
   

/>

const image2 = <img
  className="  "
  id="image0_5_5"
  width="120"
  height="136"
  alt='thiis default image'
  src="data:image/png;base64,"
  

/>

import React from 'react';


interface WelcomeCardProps {
  userName?: string;

}

const WelcomeCard: React.FC<WelcomeCardProps> = ({ userName = 'User', }) => {
  return (
<div className='p-2 mx-auto overflow-hidden'>
  <div className="relative w-full max-w-xl mx-auto bg-[#f2f2f2]
  rounded-3xl shadow-lg overflow-visible px-4 sm:px-6 md:px-10
  py-6 sm:py-7 md:py-8 text-center flex flex-col justify-center
   items-center xs:min-h-[260px] font-sans">

{/* Left Image */}
<div className="absolute -left-6 small:-left-6 sm:-left-8 md:-left-14 inset-y-0 flex items-center">
  <div className="w-[72px] h-[82px] sm:w-[90px] sm:h-[100px] md:w-[114px] md:h-[130px]">
    {image2}
  </div>
</div>

{/* Right Image */}
<div className="absolute -right-6 small:-right-6 sm:-right-8 md:-right-14 inset-y-0 flex items-center">
  <div className="w-[72px] h-[82px] sm:w-[90px] sm:h-[100px] md:w-[114px] md:h-[130px]">
    {image1}
  </div>
</div>






  {/* Heading */}
  <h1 className="text-2xl -3xl xs:text-4xl font-extrabold text-gray-900 mb-2 sm:mb-2 md:mb-3 leading-tight tracking-tight">
    Welcome, {userName}!
  </h1>

  {/* Description */}
  <p className="text-sm -base xs:text-lg text-gray-600 mb-4 sm:mb-5 md:mb-6 max-w-[90%] sm:max-w-sm md:max-w-md leading-snug">
    Start your language learning journey today!
  </p>

  {/* Button */}
  <button className="bg-gradient-to-r from-[#FF8C00] to-[#E07B00] hover:from-[#E07B00] hover:to-[#FF8C00]
   text-white font-semibold text-sm -base xs:text-lg py-3 sm:py-3.5 md:py-4 
   px-2 
   sm:px-6 md:px-9 rounded-lg uppercase shadow-md transition-transform duration-200 hover:-translate-y-0.5 hover:shadow-lg">
     Join Our Free Class
  </button>

  {/* Footer Text */}
  <p className="text-xs -xs xs:text-sm text-gray-500 mt-4 sm:mt-5 md:mt-5 italic">
    You are currently on the free version.
  </p>

</div>
</div>
  );
};

export default WelcomeCard;






